import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system_name = platform.system().lower()
    def get_cpu_usage():
        if "windows" in system_name:
            try:
                output = subprocess.check_output(["typeperf", r"\Processor(_Total)\% Processor Time", "-sc", "1"], stderr=subprocess.DEVNULL)
                lines = output.decode(errors="ignore").strip().splitlines()
                if len(lines) >= 3:
                    value_part = lines[2].split(",")[-1].strip().strip('"')
                    return float(value_part)
            except Exception:
                return 0.0
        else:
            try:
                try:
                    output = subprocess.check_output(["mpstat", "1", "1"], stderr=subprocess.DEVNULL)
                    lines = output.decode(errors="ignore").strip().splitlines()
                    for line in lines[::-1]:
                        if "all" in line:
                            parts = [p for p in line.split() if p]
                            if len(parts) >= 12:
                                idle = float(parts[-1])
                                return 100.0 - idle
                except Exception:
                    output = subprocess.check_output(["sh", "-c", "LANG=C top -bn1 | grep 'Cpu' || LANG=C top -bn1 | grep 'Cpu(s)'"], stderr=subprocess.DEVNULL)
                    line = output.decode(errors="ignore")
                    if "%" in line:
                        segments = line.split(",")
                        idle_seg = None
                        for seg in segments:
                            if "id" in seg:
                                idle_seg = seg
                                break
                        if idle_seg is not None:
                            num = "".join(ch for ch in idle_seg if (ch.isdigit() or ch == "." or ch == "," or ch == "-"))
                            num = num.replace(",", ".")
                            idle = float(num)
                            return 100.0 - idle
            except Exception:
                return 0.0
        return 0.0
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time > duration:
            break
        cpu_usage = get_cpu_usage()
        records.append({"timestamp": now, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

