import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system_name = platform.system().lower()
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time >= duration:
            break
        cpu_usage = None
        if "windows" in system_name:
            try:
                result = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage", "/value"], stderr=subprocess.STDOUT)
                text = result.decode(errors="ignore")
                for line in text.splitlines():
                    line = line.strip()
                    if line.lower().startswith("loadpercentage"):
                        parts = line.split("=", 1)
                        if len(parts) == 2:
                            try:
                                cpu_usage = float(parts[1])
                            except ValueError:
                                cpu_usage = None
                        break
            except Exception:
                cpu_usage = None
        else:
            try:
                result = subprocess.check_output(["sh", "-c", "LC_ALL=C top -bn1 | grep '%Cpu' || LC_ALL=C top -bn1 | grep 'Cpu(s)'"], stderr=subprocess.STDOUT)
                text = result.decode(errors="ignore")
                line = ""
                for l in text.splitlines():
                    if "Cpu" in l or "%Cpu" in l:
                        line = l
                        break
                if line:
                    parts = line.replace(",", " ").split()
                    idle = None
                    for i, p in enumerate(parts):
                        lp = p.lower()
                        if lp.startswith("id") or lp == "id":
                            if i > 0:
                                try:
                                    idle = float(parts[i - 1])
                                except ValueError:
                                    idle = None
                            break
                        if lp.endswith("id"):
                            num = "".join(ch for ch in lp[:-2] if ch.isdigit() or ch == "." or ch == "-")
                            if num:
                                try:
                                    idle = float(num)
                                except ValueError:
                                    idle = None
                            break
                    if idle is not None:
                        cpu_usage = 100.0 - idle
            except Exception:
                cpu_usage = None
        records.append({"timestamp": now, "cpu_usage": cpu_usage})
        sleep_end = now + interval
        while True:
            remaining = sleep_end - time.time()
            if remaining <= 0:
                break
            time.sleep(min(remaining, interval))
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH

