                out = proc.stdout
                if out:
                    line = out.replace(",", ".")
                    parts = line.split()
                    percent = None
                    for p in parts:
                        if "%" in p:
                            try:
                                percent = float(p.replace("%", ""))
                                break
                            except ValueError:
                                continue
                    if percent is None:
                        for p in parts:
                            try:
                                val = float(p)
                                percent = val
                                break
                            except ValueError:
                                continue
                    cpu_usage = percent
        except Exception:
            cpu_usage = None
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
    except (IOError, OSError):
        return None
    return LOGFILE_PATH

