import subprocess
import os
import threading

def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"{script_path} does not exist")
    process_container = {"proc": None}
    def run_script():
        proc = subprocess.Popen(["python", script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        process_container["proc"] = proc
        proc.communicate()
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    proc = process_container["proc"]
    if thread.is_alive():
        if proc is not None:
            try:
                proc.terminate()
            except Exception:
                pass
        thread.join()
        return "Terminating process due to timeout."
    return "Script executed successfully."

import subprocess
import os
import threading

def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"{script_path} does not exist")
    timed_out = {"flag": False}
    process = subprocess.Popen(["python", script_path])
    def kill_process():
        if process.poll() is None:
            timed_out["flag"] = True
            process.terminate()
    timer = threading.Timer(timeout, kill_process)
    timer.start()
    process.wait()
    timer.cancel()
    if timed_out["flag"]:
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

