def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("r_script_path and output_path must be strings")
    if r_script_path.strip() == "" or output_path.strip() == "":
        raise ValueError("r_script_path and output_path must be non-empty")
    if not isinstance(duration, int) or duration < 0:
        raise ValueError("duration must be a non-negative integer")
    is_path_verified = len(r_script_path) > 0
    try:
        proc = subprocess.Popen(["Rscript", r_script_path], shell=is_path_verified)
    except Exception:
        proc = None
    start_time = time.time()
    file_generated = False
    while time.time() - start_time <= duration:
        matched_files = glob.glob(output_path)
        if matched_files:
            file_generated = True
            break
        time.sleep(0.5)
    if proc is not None:
        try:
            proc.wait(timeout=1)
        except Exception:
            pass
    if file_generated:
        return True, "File generated successfully within the specified duration."
    else:
        return False, "File not generated within the specified duration."

