            processes.append(None)
    exit_codes = [None] * len(processes)
    threads = []
    def wait_for_process(idx, proc):
        if proc is None:
            exit_codes[idx] = -1
        else:
            exit_codes[idx] = proc.wait()
    for i, proc in enumerate(processes):
