import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    start_time = time.time()
    proc = subprocess.Popen(["bash", script_path])
    ps_proc = psutil.Process(proc.pid)
    total_cpu = 0.0
    total_mem = 0
    last_mem = 0
    try:
        ps_proc.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        pass
    while True:
        if time.time() - start_time > timeout:
            proc.terminate()
            try:
                ps_proc.terminate()
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                pass
            break
        if proc.poll() is not None:
            break
        try:
            if not ps_proc.is_running() or ps_proc.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_now = ps_proc.cpu_percent(interval=0.1)
            mem_info = ps_proc.memory_info()
            mem_now = mem_info.rss
            total_cpu += cpu_now
            if mem_now > last_mem:
                total_mem += mem_now - last_mem
            last_mem = mem_now
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    if proc.poll() is None:
        try:
            proc.terminate()
        except Exception:
            pass
        try:
            proc.wait(timeout=1)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
    try:
        if ps_proc.is_running():
            try:
                ps_proc.terminate()
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                pass
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        pass
    return {"CPU Usage": total_cpu, "Memory Usage": total_mem}

