def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    python_executable = f"python{python_version}"
    try:
        output = subprocess.check_output([python_executable, "--version"])
    except Exception as e:
        raise RuntimeError(f"Failed to switch Python version: {e}")
    version_str = output.decode("utf-8").strip()
    parts = version_str.split()
    if len(parts) >= 2:
        normalized_version = parts[1]
    else:
        normalized_version = python_version
    if path_to_append and path_to_append not in sys.path:
        sys.path.append(path_to_append)
    return normalized_version

